create table if not exists public.mz_courses(id uuid primary key default gen_random_uuid(), title text not null, description text, level text, published boolean not null default false, created_by uuid references auth.users(id), created_at timestamptz not null default now());
create table if not exists public.mz_course_lessons(id uuid primary key default gen_random_uuid(), course_id uuid not null references public.mz_courses(id) on delete cascade, title text not null, content jsonb not null default '{}'::jsonb, position int not null default 0, published boolean not null default false);
create table if not exists public.mz_course_enrollments(id uuid primary key default gen_random_uuid(), course_id uuid not null references public.mz_courses(id) on delete cascade, user_id uuid not null references auth.users(id) on delete cascade, enrolled_at timestamptz not null default now(), unique(course_id,user_id));
create table if not exists public.mz_lesson_progress(id uuid primary key default gen_random_uuid(), lesson_id uuid not null references public.mz_course_lessons(id) on delete cascade, user_id uuid not null references auth.users(id) on delete cascade, progress int not null default 0 check(progress between 0 and 100), completed_at timestamptz, updated_at timestamptz not null default now(), unique(lesson_id,user_id));
create table if not exists public.mz_assessments(id uuid primary key default gen_random_uuid(), course_id uuid not null references public.mz_courses(id) on delete cascade, title text not null, questions jsonb not null default '[]'::jsonb, passing_score int not null default 70);
create table if not exists public.mz_assessment_attempts(id uuid primary key default gen_random_uuid(), assessment_id uuid not null references public.mz_assessments(id) on delete cascade, user_id uuid not null references auth.users(id), answers jsonb not null default '{}'::jsonb, score numeric(5,2), passed boolean, submitted_at timestamptz not null default now());
alter table public.mz_courses enable row level security; alter table public.mz_course_lessons enable row level security; alter table public.mz_course_enrollments enable row level security; alter table public.mz_lesson_progress enable row level security; alter table public.mz_assessments enable row level security; alter table public.mz_assessment_attempts enable row level security;
create policy "courses public read" on public.mz_courses for select using (published or created_by=auth.uid());
create policy "lessons public read" on public.mz_course_lessons for select using (published);
create policy "own enrollment" on public.mz_course_enrollments for all using(user_id=auth.uid()) with check(user_id=auth.uid());
create policy "own progress" on public.mz_lesson_progress for all using(user_id=auth.uid()) with check(user_id=auth.uid());
create policy "assessment read" on public.mz_assessments for select using(true);
create policy "own attempts" on public.mz_assessment_attempts for all using(user_id=auth.uid()) with check(user_id=auth.uid());
